# TEMP(wstc-minimal): first, minimal run of the framework on the WSTC Dagster (NRP).
# GENERATED by scripts/build_wstc_minimal.py from images/elmfire + src/bench/previews.py.
# Do not edit the generated file; edit the template or the sources and rebuild.
#
# What it does (one job, two steps, each its own pod on NRP):
#   env_check          reports the step environment (python, arch, compiler, network)
#   elmfire_synthetic  runs the real ELMFIRE block (pyretechnics) on the synthetic test
#                      landscape and records its summary + a preview image
#
# The WSTC server only ships dagster/pandas/numpy/requests/boto3 and has no compiler, so
# the ELMFIRE step builds its own environment in the pod: uv -> CPython 3.12 -> the block's
# pinned requirements + a pre-compiled pyretechnics wheel embedded below. That is the
# stand-in for running the block's own image (ask: can steps use their own image?).
import base64
import json
import os
import platform
import shutil
import subprocess
import sys
import time
from pathlib import Path

import dagster as dg

ME = "__ME__"
GROUP = f"{ME}_bench"
WORK = Path(os.environ.get("BENCH_WORK", "/tmp/bench"))
REQUIREMENTS = __REQUIREMENTS__
BLOCK_SOURCE = __BLOCK_SOURCE__
PREVIEW_SOURCE = __PREVIEW_SOURCE__
WHEEL_NAME = "__WHEEL_NAME__"
WHEEL_B64 = "__WHEEL_B64__"


class ElmfireConfig(dg.Config):
    spread_adjustment: float = 1.5
    duration_min: float = 240.0
    band_duration_min: float = 60.0


def _sh(context, cmd, **kw):
    t = time.time()
    r = subprocess.run(cmd, capture_output=True, text=True, **kw)
    context.log.info(f"$ {' '.join(map(str, cmd))[:160]}  ({time.time() - t:.0f}s, exit {r.returncode})")
    if r.returncode != 0:
        raise RuntimeError(f"command failed: {' '.join(map(str, cmd))[:200]}\n{r.stdout[-2000:]}\n{r.stderr[-3000:]}")
    return r.stdout


@dg.asset(key_prefix=ME, group_name=GROUP, description="What a step pod on this server looks like.")
def env_check(context: dg.AssetExecutionContext) -> dict:
    import requests
    info = {
        "python": sys.version.split()[0],
        "platform": platform.platform(),
        "machine": platform.machine(),
        "cpus": os.cpu_count(),
        "c_compiler": shutil.which("gcc") or shutil.which("cc") or "none",
        "pid1_user": os.environ.get("USER") or str(os.getuid()),
    }
    for name, url in [("pypi", "https://pypi.org/simple/uv/"),
                      ("github", "https://github.com/astral-sh/python-build-standalone/releases")]:
        try:
            info[f"net_{name}"] = requests.head(url, timeout=10, allow_redirects=True).status_code
        except Exception as e:
            info[f"net_{name}"] = f"no ({type(e).__name__})"
    context.log.info(json.dumps(info))
    context.add_output_metadata(info)
    return info


@dg.asset(key_prefix=ME, group_name=GROUP,
          ins={"env_check": dg.AssetIn(key=[ME, "env_check"])},
          description="ELMFIRE block (pyretechnics) on the synthetic test landscape.",
          op_tags={"dagster-k8s/config": {"container_config": {"resources": {
              "requests": {"cpu": "2", "memory": "4Gi"},
              "limits": {"cpu": "2.4", "memory": "4800Mi"}}}}})
def elmfire_synthetic(context: dg.AssetExecutionContext, config: ElmfireConfig, env_check: dict) -> dict:
    WORK.mkdir(parents=True, exist_ok=True)
    # 1. the block's environment: uv -> CPython 3.12 -> pinned requirements + embedded wheel
    uv_dir = WORK / "uv"
    if not (uv_dir / "bin" / "uv").exists():
        _sh(context, [sys.executable, "-m", "pip", "install", "--quiet", "--target", str(uv_dir), "uv"])
    uv = str(uv_dir / "bin" / "uv")
    # keep every cache in /tmp: a pod's home directory may be read-only
    os.environ.update(UV_CACHE_DIR=str(WORK / "uv-cache"), UV_PYTHON_INSTALL_DIR=str(WORK / "pythons"))
    env_dir = WORK / "env"
    py = env_dir / "bin" / "python"
    if not py.exists():
        # the embedded wheel is for CPython 3.12: use the server's if it is 3.12, else let uv fetch one
        want = sys.executable if sys.version_info[:2] == (3, 12) else "3.12"
        context.log.info(f"block environment: Python {'(server) ' + sys.version.split()[0] if want != '3.12' else '3.12 via uv'}")
        _sh(context, [uv, "venv", "--quiet", "--python", want, str(env_dir)])
        wheel = WORK / WHEEL_NAME
        wheel.write_bytes(base64.b64decode(WHEEL_B64))
        _sh(context, [uv, "pip", "install", "--quiet", "--python", str(py), str(wheel),
                      *REQUIREMENTS, "matplotlib<3.10"])
    # 2. the block, exactly as in images/elmfire, run standalone on a run.json
    (WORK / "elmfire_block.py").write_text(BLOCK_SOURCE)
    (WORK / "previews.py").write_text(PREVIEW_SOURCE)
    run_dir = WORK / "run" / context.run_id[:8]
    run_dir.mkdir(parents=True, exist_ok=True)
    (run_dir / "run.json").write_text(json.dumps({
        "model": "elmfire", "case": {"incident": "SYNTHETIC", "crs": "EPSG:5070", "resolution_m": 30},
        "params": config.model_dump(), "inputs": {}}))
    out = _sh(context, [str(py), str(WORK / "elmfire_block.py"), str(run_dir)],
              env={**os.environ, "BENCH_ARTIFACT_ROOT": str(WORK)})
    for line in out.splitlines():
        if line and not line.startswith((" ", "{", "}", "]")):
            context.log.info(f"[elmfire] {line}")
    summary = json.loads((run_dir / "prediction" / "summary.json").read_text())
    # 3. the framework's preview, same code as src/bench/previews.py
    _sh(context, [str(py), "-c",
                  "import sys; sys.path.insert(0, sys.argv[1]); from previews import render_prediction;"
                  "render_prediction(sys.argv[2], float(sys.argv[3]))",
                  str(WORK), str(run_dir / "prediction"), str(config.duration_min)])
    png = (run_dir / "prediction" / "preview.png").read_bytes()
    context.add_output_metadata({
        **{k: (json.dumps(v) if isinstance(v, (list, dict)) else v) for k, v in summary.items()},
        "params": config.model_dump(),
        "server_python": env_check.get("python"),
        "preview": dg.MetadataValue.md(f"![preview](data:image/png;base64,{base64.b64encode(png).decode()})"),
        "dry_run": False,
    })
    return summary


defs = dg.Definitions(
    assets=[env_check, elmfire_synthetic],
    jobs=[dg.define_asset_job(f"{ME}_bench_minimal_job", selection=dg.AssetSelection.groups(GROUP))],
)
